  const x=(i:number)=>valid.length===1?50:8+i*84/(valid.length-1),weightRows=valid.filter(row=>row.weight!=null),bmiRows=valid.filter(row=>row.bmi!=null),weightMax=Math.max(1,...weightRows.map(row=>Number(row.weight))),bmiMax=Math.max(1,...bmiRows.map(row=>Number(row.bmi))),path=(key:string,max:number)=>valid.filter(row=>row[key]!=null).map(row=>`${x(valid.indexOf(row))},${78-Number(row[key])/max*58}`).join(' ')
