  const [coreRange,setCoreRange]=useState('6M'),[coreStart,setCoreStart]=useState(''),[coreEnd,setCoreEnd]=useState(''),[coreDepartment,setCoreDepartment]=useState(''),[coreDoctor,setCoreDoctor]=useState(''),[coreStatus,setCoreStatus]=useState(''),[coreType,setCoreType]=useState(''),[coreAgeGroup,setCoreAgeGroup]=useState(''),[coreGender,setCoreGender]=useState(''),[coreBloodGroup,setCoreBloodGroup]=useState(''),[coreSpecialty,setCoreSpecialty]=useState(''),[coreCompareDoctors,setCoreCompareDoctors]=useState<string[]>([]),[coreAnalytics,setCoreAnalytics]=useState<any>(null),[coreAnalyticsLoading,setCoreAnalyticsLoading]=useState(false),[coreAnalyticsError,setCoreAnalyticsError]=useState('')
  const patients=useMemo(()=>data.patients.filter(p=>`${p.first_name} ${p.last_name} ${p.patient_number} ${p.uhid} ${p.phone}`.toLowerCase().includes(search.toLowerCase())),[data.patients,search])
