  <div className="page-header"><div><div className="eyebrow">HOSPITAL OPERATIONS</div><h1>{section==='Overview'?`Welcome, ${user.name.split(' ')[0]}`:pageTitle}</h1><p>{section==='Overview'?'Live operational data from your hospital database.':`Manage ${section.toLowerCase()} records stored in the hospital database.`}</p></div><div className="header-actions">{section==='Patients'&&canManagePatients&&<button className="primary-button" onClick={()=>{setSelected(null);setDialog('patient')}}><Plus size={16}/> Register patient</button>}{section==='Appointments'&&canSchedule&&<button className="primary-button" onClick={()=>setDialog('appointment')}><Plus size={16}/> Book appointment</button>}</div></div>
  {message&&<div className="hms-message success">{message}<button onClick={()=>setMessage('')} aria-label="Dismiss"> times </button></div>}{error&&<div className="hms-message error">{error}<button onClick={()=>setError('')} aria-label="Dismiss"> times </button></div>}
