  {section==='Patients'&&<><CoreAnalyticsPanel page="PATIENTS" data={coreAnalytics} loading={coreAnalyticsLoading} error={coreAnalyticsError} filters={{range:coreRange,start:coreStart,end:coreEnd,department:coreDepartment,doctor:coreDoctor,status:coreStatus,type:coreType,ageGroup:coreAgeGroup,gender:coreGender,bloodGroup:coreBloodGroup,specialty:coreSpecialty,compareDoctors:coreCompareDoctors}} onFilter={setCoreFilter} onPatient={setSelected}/><section className="panel hms-panel"><div className="table-tools"><label className="search-field"><Search size={16}/><input placeholder="Search name, patient ID, UHID, phone" value={search} onChange={e=>setSearch(e.target.value)}/></label><span>{patients.length} patients</span></div><div className="table-wrap"><table><thead><tr><th>Patient</th><th>Patient ID / UHID</th><th>Department</th><th>Assigned doctor</th><th>Phone</th><th>Actions</th></tr></thead><tbody>{patients.map(p=><tr key={p.id}><td><strong>{p.first_name} {p.last_name}</strong><small className="table-sub">{p.gender}{p.date_of_birth?`  |  ${p.date_of_birth}`:''}</small></td><td>{p.patient_number}<small className="table-sub">{p.uhid}</small></td><td>{p.department_name||'Not recorded'}</td><td>{p.doctor_name||'Unassigned'}</td><td>{p.phone}</td><td><div className="row-actions"><button onClick={()=>setSelected(p)}>View</button>{canManagePatients&&<button onClick={()=>{setSelected(p);setDialog('patient')}}>Edit</button>}{canRecordVitals&&<button onClick={()=>{setSelected(p);setDialog('vitals')}}>Vitals</button>}</div></td></tr>)}</tbody></table>{patients.length===0&&<div className="empty-state">No matching patient records.</div>}</div></section></>}
  {section==='Appointments'&&<><CoreAnalyticsPanel page="APPOINTMENTS" data={coreAnalytics} loading={coreAnalyticsLoading} error={coreAnalyticsError} filters={{range:coreRange,start:coreStart,end:coreEnd,department:coreDepartment,doctor:coreDoctor,status:coreStatus,type:coreType,ageGroup:coreAgeGroup,gender:coreGender,bloodGroup:coreBloodGroup,specialty:coreSpecialty,compareDoctors:coreCompareDoctors}} onFilter={setCoreFilter} onPatient={setSelected}/><section className="panel hms-panel"><div className="table-tools"><label className="search-field"><Search size={16}/><input placeholder="Search appointments, patient, clinician" value={search} onChange={e=>setSearch(e.target.value)}/></label><span>{appointments.length} appointments</span></div><div className="table-wrap"><table><thead><tr><th>Date and time</th><th>Appointment</th><th>Patient</th><th>Doctor / department</th><th>Status</th><th>Update</th></tr></thead><tbody>{appointments.map(a=><tr key={a.id}><td>{dateTime(a.starts_at)}</td><td>{a.appointment_number}<small className="table-sub">{pretty(a.type)}</small></td><td>{a.patient_name}<small className="table-sub">{a.patient_number}</small></td><td>{a.doctor_name}<small className="table-sub">{a.department_name}</small></td><td><span className="status-pill">{pretty(a.status)}</span></td><td><select aria-label={`Update ${a.appointment_number}`} value={a.status} onChange={e=>startTransition(async()=>{const r=await changeAppointmentStatus(a.id,e.target.value as any);finish(r,'Appointment status saved.')})}>{['SCHEDULED','CHECKED_IN','IN_CONSULTATION','COMPLETED','CANCELLED','MISSED'].map(x=><option key={x} value={x}>{pretty(x)}</option>)}</select></td></tr>)}</tbody></table>{appointments.length===0&&<div className="empty-state">No matching appointment records.</div>}</div></section></>}
